import{_ as t,o,c as d,a5 as s}from"./chunks/framework.Bj-lFevX.js";const u=JSON.parse('{"title":"Writing messages","description":"","frontmatter":{},"headers":[],"relativePath":"dev/messages.md","filePath":"dev/messages.md"}'),a={name:"dev/messages.md"};function r(n,e,c,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="writing-messages" tabindex="-1">Writing messages <a class="header-anchor" href="#writing-messages" aria-label="Permalink to &quot;Writing messages&quot;">​</a></h1><p>How the spec pipeline words its warnings, errors and exceptions, and which level each one takes. This covers <code>Builder</code>, <code>Resolver</code>, the <code>Assembler</code>, the augmenters, the merge strategies, the compilers, plugins and the <code>Spec</code> attributes. Classic keeps its own messages until it is removed in 8.0.</p><h2 id="form" tabindex="-1">Form <a class="header-anchor" href="#form" aria-label="Permalink to &quot;Form&quot;">​</a></h2><ol><li><strong>Subject first</strong>, named as a user would search for it: <code>Schema &quot;Pet&quot;</code>, <code>Property Pet::$name</code>, <code>Operation &quot;getPets&quot;</code>. No internal class or processor names such as <code>Ref:</code>.</li><li><strong>What is wrong, then what happens</strong>, in one of the outcomes below. A hint on how to fix it follows a semicolon: <code>…, omitted; use url instead</code>.</li><li><strong>Location last</strong>, <code> in &lt;source&gt;</code>, wherever it is known. The message of an exception that caused the problem goes last instead, after a colon: <code>…, skipped: &lt;reason&gt;</code>.</li><li><strong>User values in double quotes</strong>, spec keywords bare (<code>const</code>, <code>paths</code>).</li><li><strong>Sentence case</strong>, no trailing period, no em dash.</li></ol><p>The outcomes, one phrasing each:</p><table tabindex="0"><thead><tr><th>Outcome</th><th>Phrasing</th><th>For example</th></tr></thead><tbody><tr><td>A class, member, plugin or source is not read</td><td><code>skipped</code></td><td><code>Class &quot;Foo&quot; cannot be loaded, skipped: …</code></td></tr><tr><td>Something read has no effect</td><td><code>ignored</code></td><td><code>Config option &quot;x.y&quot; is unknown, ignored</code></td></tr><tr><td>Something declared is left out of the document</td><td><code>omitted</code></td><td><code>Webhooks are not supported in OpenAPI 3.0, omitted</code></td></tr><tr><td>Something is removed after it was added</td><td><code>removed</code></td><td><code>Component &quot;#/components/schemas/Foo&quot; is unreferenced, removed</code></td></tr><tr><td>One of several declarations wins</td><td><code>the last one kept</code>, or the merge mode&#39;s own words</td><td><code>Schema &quot;Pet&quot; is declared more than once, the last one kept in …</code></td></tr><tr><td>Something takes the place of what was declared</td><td><code>using …</code></td><td><code>…, using enum fallback</code></td></tr><tr><td>A field is left without a value</td><td><code>left empty</code></td><td><code>Request body &quot;Foo&quot; in … matches no request body, left empty</code></td></tr></tbody></table><p>A message about an invalid document has no outcome: the document is written as declared.</p><p><code>MessageFormTest</code> checks rules 1 and 5 over what the scratch fixtures log.</p><h2 id="levels" tabindex="-1">Levels <a class="header-anchor" href="#levels" aria-label="Permalink to &quot;Levels&quot;">​</a></h2><p>The level is behaviour, not tone. An <code>error</code> makes <code>Result::isValid()</code> false and the CLI exit with 1.</p><table tabindex="0"><thead><tr><th>Level</th><th>When</th><th>For example</th></tr></thead><tbody><tr><td><code>error</code></td><td>The document is invalid</td><td>a required field missing, a duplicate <code>operationId</code>, a reference that resolves to nothing</td></tr><tr><td><code>error</code></td><td>Something declared is lost</td><td>a class or member skipped, a component declared twice</td></tr><tr><td><code>error</code></td><td>The configuration is wrong</td><td>an unknown config option or key</td></tr><tr><td><code>warning</code></td><td>The output differs from what was declared</td><td><code>const</code> written as <code>enum</code> in 3.0, a docblock type falling back to the type hint, two operations folded by the merge strategy, a 3.1 feature left out of a 3.0 document</td></tr><tr><td><code>warning</code></td><td>The document is valid, but likely not what was meant</td><td>an array without <code>items</code> in 3.1, a request body on <code>GET</code></td></tr><tr><td><code>notice</code></td><td>A deprecated form still works</td><td>a classic type alias</td></tr><tr><td><code>notice</code>, <code>debug</code></td><td>Information</td><td>the components cleanup removed</td></tr></tbody></table><p>A merge collision is a <code>warning</code> although one declaration loses: the merge strategy that decides it is the user&#39;s choice. So is what a compiler leaves out because the target version cannot express it, since one source may be built for several versions. What a compiler keeps although the version does not know it makes the document invalid, and is an <code>error</code>.</p><p>Exceptions are for code calling the API wrongly. The content being documented never throws: a class, member or attribute that cannot be read is skipped with an <code>error</code>, and the build goes on.</p>',13)])])}const p=t(a,[["render",r]]);export{u as __pageData,p as default};
